// LC16 selects existing protected originals. These fixed read operations cannot
// seed a fixture, grant authority, prepare an assessment or dispatch a request.
export const LC16_VECTORS=Object.freeze(['FAIL','NEW','NOT_RUN','CANCELLED','UNKNOWN','SKIPPED','EXPIRED','AFFECTED','UNKNOWN_IMPACT','FINAL_MUST_RUN','UNAFFECTED_VALID_PASS']);
const lc16Outcomes=['FAIL','NOT_RUN','CANCELLED','SKIPPED'],lc16Actions=['EXPIRED','AFFECTED','UNKNOWN_IMPACT','UNAFFECTED_VALID_PASS'];
const lc16Reads=new Set(['runtime.events.read','runtime.status','lifecycle.stage.request.inspect','lifecycle.stage.observation.read','lifecycle.qualification.origin.inspect','lifecycle.qualification.action.inspect','lifecycle.qualification.inspect','lifecycle.qualification.execution.inspect','lifecycle.qualification.execution-set.inspect']);
const lc16Ready=(value,message)=>{if(!value)throw Object.assign(new Error('NOT_READY: '+message),{code:'NOT_READY'});};
const lc16Text=v=>assert(typeof v==='string'&&v.length>0&&v.length<=512),lc16Hash=v=>assert(/^sha256:[a-f0-9]{64}$/.test(v));
function lc16Pin(v){exact(v,['ref','sha256']);assert(path.isAbsolute(v.ref)&&/^[a-f0-9]{64}$/.test(v.sha256));}
export function validateLc16Selection(config,selection){
 exact(config,['schema','candidateDigest','sourceCommit','serviceId','workspaceId','profile','vectors']);assert.equal(config.schema,'runtime-lc16-installed-selection/v1');assert.deepEqual(selection.caseIds,['LC16']);assert.equal(selection.phase,'PRE_RELEASE');assert.equal(config.candidateDigest,'sha256:'+selection.expectedManifestDigest);assert.equal(config.sourceCommit,selection.sourceCommit);lc16Text(config.serviceId);lc16Text(config.workspaceId);lc16Pin(config.profile);exact(config.vectors,LC16_VECTORS);
 for(const [vector,v]of Object.entries(config.vectors)){
  exact(v,['projectId','connection','registrationRef','caseId','currentExecution',...(lc16Outcomes.includes(vector)?['originRef','snapshot','rawReceipt']:vector==='UNKNOWN'?['stageRequestId']:vector==='FINAL_MUST_RUN'?['captureRef','rawReceipt']:lc16Actions.includes(vector)?['actionRef','snapshot','originRef',...(vector==='EXPIRED'?['assessmentGrant']:[])]:[])]);
  for(const key of ['projectId','registrationRef','caseId'])lc16Text(v[key]);lc16Pin(v.connection);exact(v.currentExecution,['caseId','captureRef','rawReceipt']);lc16Text(v.currentExecution.caseId);lc16Text(v.currentExecution.captureRef);lc16Pin(v.currentExecution.rawReceipt);assert.notEqual(v.caseId,v.currentExecution.caseId,'Current control cannot mask the selected vector');
  if(lc16Actions.includes(vector))assert.equal(v.caseId,'LC20','Current formal native producer is the complete LC20 case');for(const key of ['stageRequestId','originRef','captureRef','actionRef'])if(v[key]!==undefined)lc16Text(v[key]);for(const key of ['snapshot','rawReceipt','assessmentGrant'])if(v[key])lc16Pin(v[key]);
 }
 return config;
}
